it('reintegrates an already included Child after public Shape reconfirmation (same)', async () => {
  const f = await supervisor();
  await f.submitChild(f.run, f.baselineCli);
  let run = await f.next(f.baselineCli);
  run = await f.verifyChild(run, f.baselineCli);
  const firstIntegration = f.pending(run, 'supervisor.child.integrate');
  run = await f.next();
  const firstOutput = run.actions.find((a) => a.id === firstIntegration.id)!.outcome!.output as {
    baseCommit: string;
    candidateCommit: string;
    integrationCommit: string;
    integrationWorktree: string;
  };
  expect(
    f
      .git(firstOutput.integrationWorktree, [
        'rev-list',
        '--parents',
        '-n',
        '1',
        firstOutput.integrationCommit,
      ])
      .split(' '),
  ).toEqual([firstOutput.integrationCommit, firstOutput.baseCommit, firstOutput.candidateCommit]);
  await f.next();
  run = await f.next();
  const archivedIntegrationCommit = f.git(firstOutput.integrationWorktree, ['rev-parse', 'HEAD']);
  expect(run.actions.find((action) => action.stepId === 'supervisor.child.archive')).toMatchObject({
    status: 'succeeded',
    outcome: { output: { integrationCommit: archivedIntegrationCommit } },
  });
  const originalArchive = await f.archiveSnapshot(run, 'left');
  expect(await f.restoreArchiveMaterials(run, originalArchive.integration)).toMatchObject({
    archives: [{ archiveActionId: originalArchive.archive.id, missing: [] }],
  });
  const retainedFacts = run.actions.filter((a) => a.status === 'succeeded');
  expect(f.revise(run).exitCode).toBe(0);
  const reconfirmed = await f.confirmAgain();
  const oldBrief = path.join(originalArchive.directory, 'brief.md');
  await fs.unlink(oldBrief);
  expect(
    await f.restoreArchiveMaterials(reconfirmed, originalArchive.integration, false),
  ).toMatchObject({
    archives: [],
  });
  await expect(fs.access(oldBrief)).rejects.toMatchObject({ code: 'ENOENT' });
  await fs.writeFile(oldBrief, originalArchive.files['brief.md']);
  await f.next();
  run = await f.next();
  const builder = f.pending(run, 'supervisor.child.builder');
  const input = (
    builder.input as {
      activation: { child: string; worktree: string; baseCommit: string };
    }
  ).activation;
  expect(input.child).toBe('left');
  expect(input.baseCommit).toBe(archivedIntegrationCommit);
  f.git(input.worktree, ['merge', '--ff-only', input.baseCommit]);
  const candidate = f.git(input.worktree, ['rev-parse', 'HEAD']);
  expect(candidate).toBe(input.baseCommit);
  const claimed = await f.claim(builder);
  await f.report(
    claimed.actions.find((a) => a.id === builder.id)!,
    {
      summary: 'Revalidate the actual retained Child without a new commit',
      candidateCommit: candidate,
      verificationChecks: f.checkPlan('left'),
    },
  );
  run = await f.next();
  const checks = [...run.actions]
    .reverse()
    .find((a) => a.stepId === 'supervisor.child.builder' && a.status === 'succeeded')!;
  expect(checks.status).toBe('succeeded');
  expect(retainedFacts.some((a) => a.id === checks.id)).toBe(false);
  run = await f.verifyChild(run);
  const integration = f.pending(run, 'supervisor.child.integrate');
  const beforeHead = f.git(firstOutput.integrationWorktree, ['rev-parse', 'HEAD']);
  expect(beforeHead).toBe(archivedIntegrationCommit);
  const result = await f.dispatchResult({
    operation: 'execute',
    runId: f.name,
    actionId: integration.id,
    executorId: 'native-supervisor-integrate',
  });
  expect(result.exitCode, JSON.stringify(result)).toBe(0);
  run = await f.inspect();
  expect(run.actions.find((a) => a.id === integration.id)).toMatchObject({
    status: 'succeeded',
    claim: { executorId: 'native-supervisor-integrate' },
    outcome: {
      output: {
        candidateCommit: candidate,
        baseCommit: beforeHead,
        integrationCommit: beforeHead,
      },
    },
  });
  expect(f.git(firstOutput.integrationWorktree, ['rev-parse', 'HEAD'])).toBe(beforeHead);
  for (const fact of retainedFacts) expect(run.actions.find((a) => a.id === fact.id)).toEqual(fact);
  const integrationChecks = f.pending(run, 'supervisor.child.archive');
  expect(integrationChecks).toBeTruthy();
  expect(f.pending(run, 'supervisor.child.builder')).toBeUndefined();
  run = await f.next();
  expect(run.actions.find((a) => a.id === integrationChecks.id)).toMatchObject({
    status: 'succeeded',
    outcome: { output: { child: 'left' } },
  });
  run = await f.next();
  expect(
    (
      f.pending(run, 'supervisor.child.builder').input as {
        activation: { child: string };
      }
    ).activation.child,
  ).toBe('right');
  expect(run.definitionHashes).toEqual(f.started.definitionHashes);
  const repeatedArchive = await f.archiveSnapshot(run, 'left');
  expect(repeatedArchive.archive.id).not.toBe(originalArchive.archive.id);
  expect(repeatedArchive.receipt.archiveRef).toBe(originalArchive.receipt.archiveRef);
  expect(repeatedArchive.files['archive-source.md']).not.toEqual(
    originalArchive.files['archive-source.md'],
  );
  f.expectArchiveHistory(originalArchive);
  for (const dryRun of [true, false])
    expect(await f.restoreArchiveMaterials(run, repeatedArchive.integration, dryRun)).toMatchObject(
      {
        archives: [{ archiveActionId: repeatedArchive.archive.id, missing: [] }],
      },
    );
  const briefFile = path.join(repeatedArchive.directory, 'brief.md');
  const sourceFile = path.join(repeatedArchive.directory, 'archive-source.md');
  await fs.unlink(briefFile);
  await fs.appendFile(sourceFile, 'unbound material edit\n');
  expect(await f.restoreArchiveMaterials(run, repeatedArchive.integration, false)).toMatchObject({
    archives: [{ archiveActionId: repeatedArchive.archive.id, missing: ['brief.md'] }],
  });
  expect(await fs.readFile(sourceFile, 'utf8')).toBe(
    repeatedArchive.files['archive-source.md'].toString('utf8') + 'unbound material edit\n',
  );
  expect(await fs.readFile(briefFile)).toEqual(repeatedArchive.committedFiles['brief.md']);
  await fs.unlink(briefFile);
  await fs.writeFile(sourceFile, repeatedArchive.files['archive-source.md']);
  expect(await f.restoreArchiveMaterials(run, repeatedArchive.integration)).toMatchObject({
    archives: [{ archiveActionId: repeatedArchive.archive.id, missing: ['brief.md'] }],
  });
  await f.restoreArchiveMaterials(run, repeatedArchive.integration, false);
  for (const [ref, bytes] of Object.entries(repeatedArchive.files))
    expect(await fs.readFile(path.join(repeatedArchive.directory, ref))).toEqual(
      ref === 'brief.md' ? repeatedArchive.committedFiles[ref] : bytes,
    );
  // 已按原 Git blob 恢复的文件重新登记到索引；不引入新的归档内容。
  f.git(repeatedArchive.integration, ['add', '--', repeatedArchive.relative + '/brief.md']);
  expect(f.git(repeatedArchive.integration, ['diff', '--cached', '--name-only'])).toBe('');
  expect(await f.inspect()).toEqual(run);
  f.expectArchiveHistory(originalArchive);
  await f.submitChild(run, undefined, true);
  run = await f.next();
  run = await f.verifyChild(run);
  const pendingIntegration = f.pending(run, 'supervisor.child.integrate');
  const integrationStatus = f.git(firstOutput.integrationWorktree, ['status', '--porcelain=v1']);
  expect(integrationStatus, 'Integration must be clean before the deliberate branch drift').toBe(
    '',
  );
  await fs.writeFile(
    path.join(firstOutput.integrationWorktree, 'integration-note.txt'),
    'Actual unbound integration change\n',
  );
  f.git(firstOutput.integrationWorktree, ['add', 'integration-note.txt']);
  f.git(firstOutput.integrationWorktree, ['commit', '-m', 'unbound integration work']);
  const changedHead = f.git(firstOutput.integrationWorktree, ['rev-parse', 'HEAD']);
  const beforeDrift = await f.inspect();
  const rejectedNext = f.cli(['native', 'next', f.name, '--json']);
  expect(rejectedNext.response.error.message).toContain('branch changed after the prior check');
  const stoppedBeforeDrift = await f.inspect();
  expectOriginalActionFacts(stoppedBeforeDrift, beforeDrift.actions);
  expect({
    ...stoppedBeforeDrift,
    actions: beforeDrift.actions,
    revision: beforeDrift.revision,
  }).toEqual(beforeDrift);
  expect(stoppedBeforeDrift.revision).toBe(beforeDrift.revision);
  for (const operation of ['execute', 'claim']) {
    const request = {
      operation,
      runId: f.name,
      actionId: pendingIntegration.id,
      executorId: 'native-supervisor-integrate',
      ...(operation === 'claim'
        ? {
            attempt: pendingIntegration.attempt,
            inputHash: pendingIntegration.inputHash,
            sessionId: 'integration-preflight',
            claimToken: 'integration-preflight-claim',
          }
        : {}),
    };
    const requestFile = path.join(f.root, operation + '-drifted-integration.json');
    await fs.writeFile(requestFile, JSON.stringify(request));
    const rejected = f.cli([
      'runtime',
      'dispatch',
      '--application',
      'native',
      '--request',
      requestFile,
    ]);
    expect(rejected.response.error.message).toContain('branch changed after the prior check');
    expect(await f.inspect()).toEqual(stoppedBeforeDrift);
  }
  expect(f.git(firstOutput.integrationWorktree, ['rev-parse', 'HEAD'])).toBe(changedHead);
}, 360000)

