      }),
    ).toEqual(dispatched.task);
    expect(() =>
      reconnectNativeSupervisorTask(dispatched.state, {
        child: 'integration-core',
        runId: 'stale-run',
      }),
    ).toThrow(/runId/iu);
    const cancelled = cancelNativeSupervisorTask(dispatched.state, {
