    const initial = createNativeSupervisorState({
      parent: 'parent',
      targetBranch: 'beta20',
      targetCommit: 'a'.repeat(40),
      integrationBranch: 'comet/supervisor/parent/integration',
      integrationWorktree: 'D:/worktrees/parent-integration',
